<?php
namespace App\Http\Controllers;
use App\Models\SitePresentation;
use App\Enums\Role;
use App\Services\{SitePresentationService,AdminAuditService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Schema,Storage};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class AdminPresentationController extends Controller {
 private function owner(Request $r):void{abort_unless($r->user()?->fresh()->role===Role::Owner,403);abort_unless(Schema::hasTable('site_presentations'),503,'Jalankan migration tampilan situs terlebih dahulu.');}
 public function index(Request $r,SitePresentationService $service){$this->owner($r);return response()->view('admin.presentation',['settings'=>$service->settings(),'photo'=>$service->loginPhoto(),'registerPhoto'=>$service->registerPhoto()])->header('Cache-Control','private, no-store');}
 public function photo(Request $r,AdminAuditService $audit){$this->owner($r);$d=$r->validate(['photo'=>'required|image|mimes:jpeg,png,webp|max:5120','alt'=>'required|string|max:140|not_regex:/[<>]/','publication_consent'=>'accepted']);$file=$r->file('photo');$size=@getimagesize($file->getRealPath());if(!$size||$size[0]*$size[1]>12000000)throw ValidationException::withMessages(['photo'=>'Foto maksimal 12 juta piksel.']);if(!function_exists('imagewebp'))throw ValidationException::withMessages(['photo'=>'PHP GD/WebP wajib tersedia.']);$im=@imagecreatefromstring(file_get_contents($file->getRealPath()));if(!$im)throw ValidationException::withMessages(['photo'=>'Foto tidak dapat diproses.']);
 if(function_exists('exif_read_data')&&$file->getMimeType()==='image/jpeg'){$o=(int)((@exif_read_data($file->getRealPath()))['Orientation']??1);if(in_array($o,[2,4,5,7],true))imageflip($im,in_array($o,[2,5,7],true)?IMG_FLIP_HORIZONTAL:IMG_FLIP_VERTICAL);$a=match($o){3=>180,5,6=>-90,7,8=>90,default=>0};if($a){$rot=imagerotate($im,$a,0);imagedestroy($im);$im=$rot;}}
 $w=imagesx($im);$h=imagesy($im);if(max($w,$h)>1600){$small=imagescale($im,max(1,(int)round($w*1600/max($w,$h))),max(1,(int)round($h*1600/max($w,$h))));imagedestroy($im);$im=$small;}ob_start();$ok=imagewebp($im,null,82);$bytes=ob_get_clean();imagedestroy($im);$path='site-photos/'.Str::uuid().'.webp';if(!$ok||!Storage::disk('local')->put($path,$bytes))throw ValidationException::withMessages(['photo'=>'Foto gagal disimpan.']);$old=null;
 try{DB::transaction(function()use($r,$d,$path,&$old,$audit){$s=SitePresentation::whereKey(1)->lockForUpdate()->firstOrFail();$old=$s->login_photo_path;$s->update(['login_photo_path'=>$path,'login_photo_alt'=>$d['alt']]);$audit->write($r->user(),'site.login-photo.update','site',1,['count'=>1]);});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}if($old)Storage::disk('local')->delete($old);return to_route('admin.presentation')->with('success','Foto halaman masuk diganti. Foto lama telah dihapus.');}
 public function reset(Request $r,AdminAuditService $audit){$this->owner($r);$old=null;DB::transaction(function()use($r,$audit,&$old){$s=SitePresentation::whereKey(1)->lockForUpdate()->firstOrFail();$old=$s->login_photo_path;$s->update(['login_photo_path'=>null,'login_photo_alt'=>null]);$audit->write($r->user(),'site.login-photo.reset','site',1);});if($old)Storage::disk('local')->delete($old);return to_route('admin.presentation')->with('success','Foto halaman masuk kembali ke ilustrasi bawaan.');}
 private function processPhotoFile($file):string{$size=@getimagesize($file->getRealPath());if(!$size||$size[0]*$size[1]>12000000)throw ValidationException::withMessages(['photo'=>'Foto maksimal 12 juta piksel.']);if(!function_exists('imagewebp'))throw ValidationException::withMessages(['photo'=>'PHP GD/WebP wajib tersedia.']);$im=@imagecreatefromstring(file_get_contents($file->getRealPath()));if(!$im)throw ValidationException::withMessages(['photo'=>'Foto tidak dapat diproses.']);
 if(function_exists('exif_read_data')&&$file->getMimeType()==='image/jpeg'){$o=(int)((@exif_read_data($file->getRealPath()))['Orientation']??1);if(in_array($o,[2,4,5,7],true))imageflip($im,in_array($o,[2,5,7],true)?IMG_FLIP_HORIZONTAL:IMG_FLIP_VERTICAL);$a=match($o){3=>180,5,6=>-90,7,8=>90,default=>0};if($a){$rot=imagerotate($im,$a,0);imagedestroy($im);$im=$rot;}}
 $w=imagesx($im);$h=imagesy($im);if(max($w,$h)>1600){$small=imagescale($im,max(1,(int)round($w*1600/max($w,$h))),max(1,(int)round($h*1600/max($w,$h))));imagedestroy($im);$im=$small;}ob_start();$ok=imagewebp($im,null,82);$bytes=ob_get_clean();imagedestroy($im);$path='site-photos/'.Str::uuid().'.webp';if(!$ok||!Storage::disk('local')->put($path,$bytes))throw ValidationException::withMessages(['photo'=>'Foto gagal disimpan.']);return $path;}
 public function registerPhoto(Request $r,AdminAuditService $audit){$this->owner($r);$d=$r->validate(['photo'=>'required|image|mimes:jpeg,png,webp|max:5120','alt'=>'required|string|max:140|not_regex:/[<>]/','publication_consent'=>'accepted']);$path=$this->processPhotoFile($r->file('photo'));$old=null;
 try{DB::transaction(function()use($r,$d,$path,&$old,$audit){$s=SitePresentation::whereKey(1)->lockForUpdate()->firstOrFail();$old=$s->register_photo_path;$s->update(['register_photo_path'=>$path,'register_photo_alt'=>$d['alt']]);$audit->write($r->user(),'site.register-photo.update','site',1,['count'=>1]);});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}if($old)Storage::disk('local')->delete($old);return to_route('admin.presentation')->with('success','Foto halaman daftar diganti. Foto lama telah dihapus.');}
 public function resetRegister(Request $r,AdminAuditService $audit){$this->owner($r);$old=null;DB::transaction(function()use($r,$audit,&$old){$s=SitePresentation::whereKey(1)->lockForUpdate()->firstOrFail();$old=$s->register_photo_path;$s->update(['register_photo_path'=>null,'register_photo_alt'=>null]);$audit->write($r->user(),'site.register-photo.reset','site',1);});if($old)Storage::disk('local')->delete($old);return to_route('admin.presentation')->with('success','Foto halaman daftar kembali ke ilustrasi bawaan.');}
 public function contact(Request $r,SitePresentationService $service,AdminAuditService $audit){$this->owner($r);$r->validate(['help_contact'=>'nullable|string|max:300','publication_consent'=>'accepted']);$contact=$service->validateContact($r->input('help_contact'));DB::transaction(function()use($r,$contact,$audit){SitePresentation::whereKey(1)->lockForUpdate()->firstOrFail()->update(['help_contact'=>$contact]);$audit->write($r->user(),'site.help-contact.update','site',1,['enabled'=>(bool)$contact]);});return to_route('admin.presentation')->with('success','Kontak bantuan platform disimpan.');}
 public function publicPhoto(SitePresentationService $service){return $service->photo();}
 public function publicRegisterPhoto(SitePresentationService $service){return $service->registerPhotoFile();}
}
